import fs from 'node:fs/promises';
const root = '/tmp/oxi-browser-audit-20261027';
const runId = process.env.TASK_AUDIT_RUN ?? 'repeat';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
async function run(name, endpoint) {
  const ws = new WebSocket(endpoint);
  let id = 0;
  const pending = new Map();
  const report = { name, endpoint, cases: {}, events: [] };
  ws.onmessage = ({data}) => {
    const m = JSON.parse(data);
    if (m.id) {
      const p = pending.get(m.id);
      if (!p) return;
      clearTimeout(p.timer); pending.delete(m.id);
      if (m.error) p.reject(new Error(JSON.stringify(m.error))); else p.resolve(m.result);
    } else if (['Runtime.exceptionThrown','Runtime.consoleAPICalled'].includes(m.method)) report.events.push(m);
  };
  const send = (method, params = {}) => new Promise((resolve,reject) => {
    const n = ++id;
    const timer = setTimeout(() => { pending.delete(n); reject(new Error(method + ' timeout')); }, 20000);
    pending.set(n,{resolve,reject,timer}); ws.send(JSON.stringify({id:n,method,params}));
  });
  const evaluate = async (expression, awaitPromise = false) => {
    const r = await send('Runtime.evaluate',{expression,awaitPromise,returnByValue:true});
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
    return r.result?.value;
  };
  const check = async (key, expression, awaitPromise = false) => {
    try { report.cases[key] = JSON.parse(await evaluate(expression,awaitPromise)); }
    catch (error) { report.cases[key] = {error:String(error)}; }
  };
  try {
    await new Promise((resolve,reject) => { ws.onopen=resolve; ws.onerror=reject; });
    await send('Page.enable'); await send('Runtime.enable');
    await send('Page.navigate',{url:'http://127.0.0.1:19237/index.html'});
    await sleep(500);
    await check('globals', `JSON.stringify(Object.fromEntries(['Worker','SharedWorker','AudioContext','OfflineAudioContext','MediaSource','MediaRecorder','RTCPeerConnection','OffscreenCanvas','MessageChannel','FileReader','CSSStyleSheet','Range','Selection'].map(n=>[n,typeof globalThis[n]])))`);
    await check('window_and_dom', `JSON.stringify((()=>{const n=document.getElementById('box');n.auditExpando=42;return {windowGlobal:window===globalThis,windowSelf:window===self,windowComputedStyle:typeof window.getComputedStyle,nodeIdentity:n===document.getElementById('box'),expando:document.getElementById('box').auditExpando,computedColor:getComputedStyle(n).color,computedWidth:getComputedStyle(n).width}})())`);
    await check('canvas2d', `JSON.stringify((()=>{const c=document.createElement('canvas');c.width=c.height=2;const x=c.getContext('2d');x.fillStyle='#ff0000';x.fillRect(0,0,1,1);return {context:!!x,pixel:Array.from(x.getImageData(0,0,1,1).data)}})())`);
    await check('focus_validation', `JSON.stringify((()=>{const a=document.getElementById('focus');a.focus();const required=document.getElementById('required');return {activeId:document.activeElement?.id,checkValidity:typeof required.checkValidity,valid:typeof required.checkValidity==='function'?required.checkValidity():null}})())`);
    await check('event_options', `JSON.stringify((()=>{const order=[];let once=0;const p=document.getElementById('parent'),t=document.getElementById('target');document.addEventListener('audit-event',()=>order.push('capture'),true);t.addEventListener('audit-event',()=>order.push('target'));p.addEventListener('audit-event',()=>order.push('parent'));document.addEventListener('audit-event',()=>order.push('bubble'));t.addEventListener('audit-once',()=>once++,{once:true});t.dispatchEvent(new Event('audit-event',{bubbles:true}));t.dispatchEvent(new Event('audit-once'));t.dispatchEvent(new Event('audit-once'));return {order,once}})())`);
    await check('webgl2', `JSON.stringify((()=>{const c=document.createElement('canvas'),g=c.getContext('webgl2');const names=['createQuery','bindBufferBase','texImage3D','drawBuffers','renderbufferStorageMultisample','createTransformFeedback','fenceSync','texStorage2D'];return {context:!!g,methods:Object.fromEntries(names.map(n=>[n,typeof g?.[n]]))}})())`);
    await check('crypto_wasm', `JSON.stringify({crypto:Object.fromEntries(['digest','encrypt','decrypt','sign','verify','deriveKey','generateKey'].map(n=>[n,typeof crypto.subtle?.[n]])),wasm:Object.fromEntries(['Module','Instance','Global','compileStreaming','instantiateStreaming'].map(n=>[n,typeof WebAssembly[n]]))})`);
    await check('iframe', `JSON.stringify((()=>{const f=document.getElementById('frame');return {contentWindow:typeof f.contentWindow,contentDocument:typeof f.contentDocument,text:f.contentDocument?.getElementById('child')?.textContent}})())`);
    await check('idb', `new Promise(resolve=>{try{const q=indexedDB.open('audit-'+Date.now(),1);q.onerror=()=>resolve(JSON.stringify({error:String(q.error)}));q.onupgradeneeded=()=>{const s=q.result.createObjectStore('items');resolve(JSON.stringify({createIndex:typeof s.createIndex,openCursor:typeof s.openCursor,abort:typeof q.transaction?.abort}));};}catch(e){resolve(JSON.stringify({error:String(e)}));}})`,true);
    await check('binary_fetch', `fetch('/binary').then(async r=>JSON.stringify({bytes:Array.from(new Uint8Array(await r.arrayBuffer())),bodyType:typeof r.body,reader:typeof r.body?.getReader}))`,true);
    await evaluate(`globalThis.auditStyleLoaded=false;const link=document.createElement('link');link.rel='stylesheet';link.href='/late.css';link.onload=()=>auditStyleLoaded=true;document.head.appendChild(link);globalThis.auditTicks=0;globalThis.auditTimer=setInterval(()=>auditTicks++,50);`);
    await sleep(1000);
    await check('styles_and_timers', `JSON.stringify({loaded:auditStyleLoaded,color:getComputedStyle(document.getElementById('late')).color,animationWidth:getComputedStyle(document.getElementById('anim')).width,ticks:auditTicks})`);
    await evaluate('clearInterval(auditTimer)');
    report.cases.object_reference = await send('Runtime.evaluate',{expression:'({audit:42})',returnByValue:false});
    try { report.cases.debugger = await send('Debugger.enable'); } catch(e) { report.cases.debugger={error:String(e)}; }
    const doc = await send('DOM.getDocument',{depth:-1});
    const selected = await send('DOM.querySelector',{nodeId:doc.root.nodeId,selector:'#upload'});
    try { await send('DOM.setFileInputFiles',{nodeId:selected.nodeId,files:[root+'/sample.txt']});
      await check('file_upload', `JSON.stringify((()=>{const i=document.getElementById('upload');return {value:i.value,length:i.files?.length??null,name:i.files?.[0]?.name??null}})())`);
    } catch(e) { report.cases.file_upload={error:String(e)}; }
    await send('Page.navigate',{url:'http://127.0.0.1:19237/react.html'});
    const hasCounter = node => (node.attributes??[]).some((v,i,a)=>v==='id'&&a[i+1]==='counter') || (node.children??[]).some(hasCounter);
    let mounted = false;
    for (let i=0;i<30;i++) {
      const tree = await send('DOM.getDocument',{depth:-1});
      if (hasCounter(tree.root)) { mounted=true; break; }
      await sleep(200);
    }
    report.cases.react18 = {mounted};
    if (mounted) {
      report.cases.react18.before = await evaluate("document.getElementById('counter').textContent");
      await evaluate("document.getElementById('counter').click()"); await sleep(300);
      report.cases.react18.after = await evaluate("document.getElementById('counter').textContent");
    }
  } catch (error) { report.error=String(error); }
  finally { for(const p of pending.values())clearTimeout(p.timer);ws.close();await fs.writeFile(root+'/'+name+'-'+runId+'.json',JSON.stringify(report,null,2)); }
  console.log(JSON.stringify({name,cases:report.cases,error:report.error}));
}
await run('oxibrowser','ws://127.0.0.1:19236/ws');
const tabs=await (await fetch('http://127.0.0.1:19238/json/list')).json();
await run('chrome',tabs.find(t=>t.type==='page').webSocketDebuggerUrl);

