import fs from 'node:fs/promises';
const root='/tmp/oxi-browser-audit-20261027';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function inspect(name,url) {
 const ws=new WebSocket(url);let id=0;const pending=new Map();
 ws.onmessage=({data})=>{const m=JSON.parse(data);const p=pending.get(m.id);if(p){clearTimeout(p.t);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}};
 await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
 const send=(method,params={})=>new Promise((resolve,reject)=>{const n=++id,t=setTimeout(()=>reject(new Error(method+' timeout')),20000);pending.set(n,{resolve,reject,t});ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true});if(r.exceptionDetails)throw r.exceptionDetails;return r.result.value;};
 const result={name};
 try{
  await send('Page.enable');await send('Page.navigate',{url:'http://127.0.0.1:19237/layout.html'});await sleep(300);
  result.layout=JSON.parse(await evaluate(`JSON.stringify((()=>{const b=document.getElementById('box'),r=b.getBoundingClientRect();return {computedWidth:getComputedStyle(b).width,computedColor:getComputedStyle(b).color,rect:{x:r.x,y:r.y,width:r.width,height:r.height},HTMLIFrameElementGlobal:typeof globalThis.HTMLIFrameElement,HTMLIFrameElementWindow:typeof window.HTMLIFrameElement,windowDocument:window.document===document}})())`));
  if(name!=='oxibrowser-default'){const shot=await send('Page.captureScreenshot',{format:'png'});await fs.writeFile(root+'/'+name+'-layout.png',Buffer.from(shot.data,'base64'));}
  await evaluate('globalThis.freeTicks=0;globalThis.freeTimer=setInterval(()=>freeTicks++,20)');
  const start=Date.now();await sleep(500);result.idle={hostWaitMs:Date.now()-start,ticks:await evaluate('freeTicks')};await evaluate('clearInterval(freeTimer)');
 }catch(error){result.error=String(error)}finally{for(const p of pending.values())clearTimeout(p.t);ws.close();}
 await fs.writeFile(root+'/'+name+'-supplement.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}
await inspect('oxibrowser','ws://127.0.0.1:19236/ws');
await inspect('oxibrowser-default','ws://127.0.0.1:19239/ws');
const tabs=await (await fetch('http://127.0.0.1:19238/json/list')).json();await inspect('chrome',tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
